+    e.preventDefault();
+    const results = evaluateQuiz();
+    displayResults(results);
+});
+
+function evaluateQuiz() {
+    const q1Answers = getCheckedValues('q1');
+    const q2Answers = getCheckedValues('q2');
+    const q3Answers = getCheckedValues('q3');
+
+    // Correct answers for each question
+    const correctAnswers = {
+        q1: ['python', 'javascript'],
+        q2: ['python', 'nodejs', 'go'],
+        q3: ['cplus', 'rust', 'go']
+    };
+
+    const questions = [
+        {
+            number: 1,
+            text: 'Which of the following are dynamically typed languages?',
+            userAnswers: q1Answers,
+            correctAnswers: correctAnswers.q1
+        },
+        {
+            number: 2,
+            text: 'Which languages are commonly used for web backend development?',
+            userAnswers: q2Answers,
+            correctAnswers: correctAnswers.q2
+        },
+        {
+            number: 3,
+            text: 'Which of these languages compile to machine code?',
+            userAnswers: q3Answers,
+            correctAnswers: correctAnswers.q3
+        }
+    ];
+
+    let correctCount = 0;
+
+    questions.forEach(q => {
+        const isCorrect = arraysEqual(q.userAnswers, q.correctAnswers);
+        q.isCorrect = isCorrect;
+        if (isCorrect) correctCount++;
+    });
+
+    return {
+        questions,
+        score: correctCount,
+        total: questions.length,
+        percentage: Math.round((correctCount / questions.length) * 100)
+    };
+}
+
+function getCheckedValues(name) {
+    const checkboxes = document.querySelectorAll(`input[name="${name}"]:checked`);
+    return Array.from(checkboxes)
+        .map(cb => cb.value)
+        .sort();
+}
+
+function arraysEqual(a, b) {
+    if (a.length !== b.length) return false;
+    return a.every((val, index) => val === b[index]);
+}
+
+function getAnswerDisplay(value) {
+    const answerMap = {
+        python: 'Python',
+        java: 'Java',
+        javascript: 'JavaScript',
+        rust: 'Rust',
+        nodejs: 'Node.js (JavaScript)',
+        go: 'Go',
+        css: 'CSS',
+        cplus: 'C++'
+    };
+    return answerMap[value] || value;
+}
+
+function displayResults(results) {
+    const formSection = document.querySelector('.quiz-form');
+    const resultsSection = document.getElementById('resultsSection');
+    const resultsContent = document.getElementById('resultsContent');
+
+    let html = `
+        <div class="score-summary">
+            <h3>Your Score: ${results.score} out of ${results.total} (${results.percentage}%)</h3>
+        </div>
+    `;
+
+    results.questions.forEach(q => {
+        const statusClass = q.isCorrect ? 'result-correct' : 'result-incorrect';
+        const statusText = q.isCorrect ? '✓ Correct' : '✗ Incorrect';
+
+        html += `
+            <div class="result-item">
+                <div class="result-question">Question ${q.number}: ${q.text}</div>
+                <div class="result-answer ${statusClass}">${statusText}</div>
+                <div class="result-answer"><strong>Expected:</strong> ${q.correctAnswers.map(getAnswerDisplay).join(', ')}</div>
+                <div class="result-answer"><strong>Your answer:</strong> ${q.userAnswers.length > 0 ? q.userAnswers.map(getAnswerDisplay).join(', ') : '(no selection)'}</div>
+            </div>
+        `;
+    });
+
+    resultsContent.innerHTML = html;
+    formSection.style.display = 'none';
+    resultsSection.classList.remove('hidden');
+    window.scrollTo(0, 0);
+}
+
')
